CREATE TABLE roles (code VARCHAR(20) PRIMARY KEY,name VARCHAR(80) NOT NULL);
INSERT INTO roles VALUES ('admin','Administrateur'),('manager','Responsable');
CREATE TABLE users (id SERIAL PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(190) NOT NULL,password_hash VARCHAR(200) NOT NULL,role VARCHAR(20) NOT NULL REFERENCES roles(code),active SMALLINT NOT NULL DEFAULT 1 CHECK(active IN(0,1)));
CREATE UNIQUE INDEX users_email_unique ON users(lower(email));
CREATE TABLE sessions(token_hash CHAR(64) PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),expires_at TIMESTAMPTZ NOT NULL);
CREATE INDEX sessions_expiration ON sessions(expires_at);
CREATE TABLE login_attempts(attempt_key CHAR(64) PRIMARY KEY,attempts INTEGER NOT NULL,window_start TIMESTAMPTZ NOT NULL);
CREATE TABLE categories(id SERIAL PRIMARY KEY,name VARCHAR(100) NOT NULL,parent_id INTEGER REFERENCES categories(id),sort_order INTEGER NOT NULL DEFAULT 0,active SMALLINT NOT NULL DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE units(id SERIAL PRIMARY KEY,name VARCHAR(40) UNIQUE NOT NULL);
CREATE TABLE warehouses(id SERIAL PRIMARY KEY,name VARCHAR(100) NOT NULL,active SMALLINT NOT NULL DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE locations(id SERIAL PRIMARY KEY,warehouse_id INTEGER NOT NULL REFERENCES warehouses(id),name VARCHAR(100) NOT NULL,UNIQUE(warehouse_id,name));
CREATE TABLE partners(id SERIAL PRIMARY KEY,name VARCHAR(150) NOT NULL,kind VARCHAR(20) NOT NULL CHECK(kind IN('supplier','customer')),email VARCHAR(190),active SMALLINT NOT NULL DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE products(id SERIAL PRIMARY KEY,sku VARCHAR(60) UNIQUE NOT NULL,name VARCHAR(150) NOT NULL,category_id INTEGER NOT NULL REFERENCES categories(id),unit_id INTEGER NOT NULL REFERENCES units(id),barcode VARCHAR(80) UNIQUE,minimum NUMERIC(18,3) NOT NULL DEFAULT 0 CHECK(minimum>=0),cost NUMERIC(18,4) NOT NULL DEFAULT 0 CHECK(cost>=0),active SMALLINT NOT NULL DEFAULT 1 CHECK(active IN(0,1)));
CREATE INDEX products_name ON products(name);
CREATE TABLE stock_balances(warehouse_id INTEGER NOT NULL REFERENCES warehouses(id),product_id INTEGER NOT NULL REFERENCES products(id),quantity NUMERIC(18,3) NOT NULL DEFAULT 0 CHECK(quantity>=0),minimum NUMERIC(18,3) CHECK(minimum>=0),PRIMARY KEY(warehouse_id,product_id));
CREATE TABLE counters(kind VARCHAR(10) NOT NULL,year SMALLINT NOT NULL,value BIGINT NOT NULL,PRIMARY KEY(kind,year));
CREATE TABLE documents(id SERIAL PRIMARY KEY,reference VARCHAR(40) UNIQUE,kind VARCHAR(20) NOT NULL CHECK(kind IN('IN','OUT','TRANSFER','REVERSAL')),status VARCHAR(20) NOT NULL DEFAULT 'draft' CHECK(status IN('draft','validated','cancelled')),warehouse_id INTEGER NOT NULL REFERENCES warehouses(id),destination_id INTEGER REFERENCES warehouses(id),partner_id INTEGER REFERENCES partners(id),reason VARCHAR(255) NOT NULL,author_id INTEGER NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),validated_at TIMESTAMPTZ,reversal_of INTEGER UNIQUE REFERENCES documents(id),idempotency_key VARCHAR(100) UNIQUE,external_reference VARCHAR(100),request_key VARCHAR(100) UNIQUE,request_hash CHAR(64));
CREATE INDEX documents_chronology ON documents(status,validated_at,id);
CREATE TABLE document_lines(id SERIAL PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES documents(id),product_id INTEGER NOT NULL REFERENCES products(id),quantity NUMERIC(18,3) NOT NULL CHECK(quantity>0),unit_cost NUMERIC(18,4) CHECK(unit_cost>=0),UNIQUE(document_id,product_id));
CREATE TABLE ledger(id SERIAL PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES documents(id),warehouse_id INTEGER NOT NULL REFERENCES warehouses(id),product_id INTEGER NOT NULL REFERENCES products(id),quantity NUMERIC(18,3) NOT NULL,occurred_at TIMESTAMPTZ NOT NULL);
CREATE INDEX ledger_chronology ON ledger(warehouse_id,product_id,occurred_at,id);
CREATE TABLE audit(id SERIAL PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),action VARCHAR(80) NOT NULL,document_id INTEGER REFERENCES documents(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE app_settings(id SMALLINT PRIMARY KEY,currency CHAR(3) NOT NULL DEFAULT 'EUR',organisation VARCHAR(100) NOT NULL DEFAULT 'StockMaster',timezone VARCHAR(80) NOT NULL DEFAULT 'Africa/Johannesburg');
INSERT INTO app_settings(id) VALUES(1);
